static const z_t6605_t _zag3153 = { { .data = "chan_free", .size = 9 }, { .length = 1, .data = _zag3151 }, { .length = 3, .data = _zag3152 }, { .data = "/* the block, once neither end holds it; the lock is not held */\nstatic void z_chan_free(z_chan* b) {\n    free(b->ring);\n    z_cond_destroy(&b->notFull);\n    z_cond_destroy(&b->notEmpty);\n    z_mutex_destroy(&b->m);\n    free(b);\n}", .size = 230 } };
